var n=`0655-egusi-soup`;var t=`world-0655`;var a=`NG`;var s=`western-africa`;var r=4;var o=93;var g={en:`Egusi Soup`,ua:`Суп егусі`};var l={en:`Egusi Soup is a Nigeria classic prepared with goat meat, yellow onion, crayfish, scotch bonnet pepper. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Spinach stands in for regional Nigerian soup greens; ground egusi, palm oil and crayfish retain the defining flavor base.`,ua:`Суп егусі, страва кухні країни Нігерія зі складниками: козлятина, жовта цибуля, річковий рак, перець скотч-боннет. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Шпинат замінює місцеву зелень; мелені зерна егусі, пальмова олія та раки зберігають характерну основу.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`goat-meat`,580,`g`],[`red-palm-oil`,80,`ml`],[`yellow-onion`,160,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`water`,720,`ml`],[`crayfish`,150,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`dawadawa`,20,`g`]]},{en:`Mix ground egusi with a little water into a thick paste; add in small lumps to the hot palm-oil broth and let them set gently.`,ua:`Розмішайте мелене егусі з невеликою кількістю води до густої пасти; покладіть невеликі порції в гарячий бульйон із пальмовою олією й дайте схопитися.`,t:[`mixing`],m:8,i:[[`ground-egusi`,240,`g`],[`water`,150,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`spinach`,290,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[]}];var u={slug:n,id:t,country:`NG`,region:s,servings:4,minutes:93,title:g,text:l,steps:d};export{a as country,u as default,t as id,o as minutes,s as region,r as servings,n as slug,d as steps,l as text,g as title};